// Prepare Data: parse both model outputs, build the Doc note, email and approval preview.

function getText(item) {
  const j = (item && item.json) || {};
  if (typeof j.output === 'string') return j.output;
  if (Array.isArray(j.output)) {
    // With web search on, output[] contains a web_search_call first, then the message.
    for (const o of j.output) {
      if (o && o.type === 'message' && Array.isArray(o.content)) {
        const c = o.content.find(x => typeof x.text === 'string');
        if (c) return c.text;
      }
    }
    for (const o of j.output) {
      if (o && Array.isArray(o.content) && o.content[0] && typeof o.content[0].text === 'string') {
        return o.content[0].text;
      }
    }
  }
  if (typeof j.text === 'string') return j.text;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  throw new Error('Could not find model text in: ' + JSON.stringify(j).slice(0, 500));
}

function parseJson(text, label) {
  const s = text.replace(/```json|```/gi, '').trim();
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error(label + ' did not return JSON: ' + s.slice(0, 300));
  return JSON.parse(s.slice(a, b + 1));
}

const arr = v => Array.isArray(v) ? v.filter(Boolean).map(String) : (v ? [String(v)] : []);
const stripQuotes = q => q.replace(/^["“”']+|["“”']+$/g, '').trim();

const pulse = parseJson(getText($('Message a model1').first()), 'Weekly Pulse model');
const fee = parseJson(getText($('Message a model2').first()), 'Fee Explainer model');
const form = $('On form submission').first().json;

const product = String(form.product_name || 'Product').trim();
const date = $now.toFormat('yyyy-MM-dd');
const lastChecked = $now.toFormat('dd LLL yyyy, HH:mm ZZZZ');

const topThemes = arr(pulse.top_themes);
const quotes = arr(pulse.supporting_quotes).map(stripQuotes);
const actions = arr(pulse.action_ideas);
const keyObservation = String(pulse.key_observation || '');

const feeIssue = String(fee.identified_fee_issue || '');
const reviewSignal = String(fee.user_confusion_from_reviews || '');
const bullets = arr(fee.explanation_bullets).slice(0, 6);
const sources = arr(fee.source_links).slice(0, 2);

// ---------- Weekly pulse (<=250 words) ----------
const weeklyPulse = [
  'Top themes:',
  ...topThemes.map(t => '• ' + t),
  '',
  'What users are saying:',
  ...quotes.map(q => '"' + q + '"'),
  '',
  'Key observation:',
  keyObservation,
  '',
  'Action ideas for the product team:',
  ...actions.map((a, i) => (i + 1) + '. ' + a)
].join('\n');
const pulseWords = weeklyPulse.split(/\s+/).filter(Boolean).length;

// ---------- Fee explainer snippet ----------
const feeSnippet = [
  'Fee: ' + feeIssue,
  '',
  ...bullets.map(b => '• ' + b),
  '',
  'Official sources:',
  ...sources.map(s => '• ' + s),
  '',
  'Last checked: ' + lastChecked
].join('\n');

// ---------- Structured record required by the brief ----------
const record = {
  date,
  top_themes: topThemes,
  weekly_pulse: weeklyPulse,
  identified_fee_issue: feeIssue,
  explanation_bullets: bullets,
  source_links: sources
};

const line = '='.repeat(60);

const docNote = [
  '',
  line,
  'WEEKLY PRODUCT PULSE — ' + product + ' — ' + date,
  line,
  '',
  'Date: ' + date,
  '',
  'Top Themes:',
  ...topThemes.map(t => '• ' + t),
  '',
  'Weekly Pulse:',
  weeklyPulse,
  '',
  'Identified Fee Issue:',
  feeIssue,
  reviewSignal ? 'Review signal: ' + reviewSignal : '',
  '',
  'Explanation:',
  ...bullets.map(b => '• ' + b),
  '',
  'Official Sources:',
  ...sources.map(s => '• ' + s),
  '',
  'Last checked: ' + lastChecked,
  '',
  'Structured record (JSON):',
  JSON.stringify(record, null, 2),
  ''
].join('\n');

const subject = 'Weekly Product Pulse + Customer Clarification — ' + product + ' (' + date + ')';

const emailBody = [
  'Hi team,',
  '',
  'Here is this week\'s product pulse for ' + product + ', plus a reusable support snippet for the fee users keep asking about.',
  '',
  '----- WEEKLY PRODUCT PULSE -----',
  '',
  weeklyPulse,
  '',
  '----- CUSTOMER FEE/CHARGE CLARIFICATION (reusable support snippet) -----',
  '',
  feeSnippet,
  '',
  'Thanks'
].join('\n');

// ---------- Quality checks shown on the approval page ----------
const warnings = [];
if (pulseWords > 250) warnings.push('Weekly pulse is ' + pulseWords + ' words (limit 250).');
if (topThemes.length < 2 || topThemes.length > 4) warnings.push('Expected 2-4 top themes, got ' + topThemes.length + '.');
if (quotes.length < 2) warnings.push('Fewer than 2 user quotes.');
if (actions.length !== 3) warnings.push('Expected 3 action ideas, got ' + actions.length + '.');
if (arr(fee.explanation_bullets).length > 6) warnings.push('Fee explainer had more than 6 bullets; trimmed to 6.');
if (sources.length !== 2) warnings.push('Expected 2 official source links, got ' + sources.length + '.');
if (!feeIssue || /none found|no recurring/i.test(feeIssue)) warnings.push('No recurring fee/charge confusion was identified.');

const preview = [
  warnings.length ? '⚠ CHECKS:\n' + warnings.map(w => '- ' + w).join('\n') + '\n' : '✅ All format checks passed.\n',
  'If approved, the following will be APPENDED to the Google Doc and saved as a Gmail DRAFT (not sent).',
  '',
  'EMAIL SUBJECT: ' + subject,
  '',
  docNote
].join('\n');

return [{
  json: {
    product,
    date,
    last_checked: lastChecked,
    subject,
    doc_note: docNote,
    email_body: emailBody,
    record,
    pulse_word_count: pulseWords,
    warnings,
    preview
  }
}];

